<template>
  <section class="audit-page page-section"><div class="container audit-page__inner">
    <header class="audit-head"><span>Контроль</span><h1 class="page-title">История действий</h1><p>Журнал не удаляется вместе с товаром или отключённым менеджером. Здесь видно, кто и когда менял каталог, скидки, заказы, рассылки и права.</p></header>
    <div class="card audit-filters"><label class="field"><span class="field__label">Поиск</span><input v-model="filters.search" class="field__input" placeholder="товар, заказ, действие"></label><label class="field"><span class="field__label">Сотрудник</span><AppSelect v-model="filters.actor_user_id" :options="staffOptions" aria-label="Сотрудник" /></label><label class="field"><span class="field__label">Объект</span><AppSelect v-model="filters.entity_type" :options="entityOptions" aria-label="Тип объекта" /></label><label class="field"><span class="field__label">С даты</span><input v-model="filters.date_from" class="field__input" type="date"></label></div>
    <div class="audit-list"><article v-for="item in items" :key="item.id" class="card audit-row"><div class="audit-row__time"><strong>{{ date(item.created_at) }}</strong><span>{{ time(item.created_at) }}</span></div><div class="audit-row__body"><strong>{{ actionLabel(item.action) }}</strong><span>{{ item.entity_label || `${entityLabel(item.entity_type)} #${item.entity_id||'—'}` }}</span></div><div class="audit-row__actor"><span>Кто</span><strong>{{ item.actor?.email || (item.action==='order.customer_cancel'?'Покупатель':'Система/гость') }}</strong></div><details v-if="item.details"><summary>Детали</summary><pre>{{ JSON.stringify(item.details,null,2) }}</pre></details></article></div>
    <p v-if="!items.length" class="card audit-empty">Записей по этим фильтрам нет.</p>
  </div></section>
</template>
<script setup>
import AppSelect from '~/components/ui/AppSelect.vue'
definePageMeta({layout:'admin',middleware:'admin'})
import {useAuthStore} from '~/stores/auth';import {createApiUrl} from '~/utils/api'
const auth=useAuthStore(),items=ref([]),staff=ref([]),filters=reactive({search:'',actor_user_id:'',entity_type:'',date_from:''})
const staffOptions=computed(()=>[{value:'',label:'Все'},...staff.value.map(u=>({value:u.id,label:u.email}))])
const entityOptions=[{value:'',label:'Все'},{value:'product',label:'Товары'},{value:'category',label:'Категории'},{value:'order',label:'Заказы'},{value:'discount_rule',label:'Скидки'},{value:'campaign',label:'Рассылки'},{value:'user',label:'Пользователи'}]
const load=async()=>{const r=await auth.authFetch(createApiUrl('/audit/admin'),{query:{...filters,limit:100}});items.value=r.items||[]}
const loadStaff=async()=>{const r=await auth.authFetch(createApiUrl('/staff/admin/users'),{query:{limit:100}});staff.value=(r.items||[]).filter(x=>['admin','manager'].includes(x.role))}
let timer;watch(()=>[filters.search,filters.actor_user_id,filters.entity_type,filters.date_from],()=>{clearTimeout(timer);timer=setTimeout(load,300)},{deep:true});onBeforeUnmount(()=>clearTimeout(timer));onMounted(async()=>{if(!auth.is_initialized)await auth.initAuth();await Promise.all([load(),loadStaff()])})
const actionMap={'product.create':'Создан товар','product.update':'Изменён товар','product.delete':'Удалён товар','product.media_add':'Добавлены медиа','product.media_delete':'Удалено медиа','category.create':'Создана категория','category.update':'Изменена категория','category.delete':'Удалена категория','discount.create':'Создано правило скидки','discount.update':'Изменено правило скидки','discount.delete':'Удалено правило скидки','campaign.create':'Создана рассылка','campaign.send':'Отправлена рассылка','order.assign':'Изменён ответственный','order.status':'Изменён статус заказа','order.update':'Изменён заказ','order.customer_cancel':'Заказ отменён покупателем','staff.update':'Изменены права пользователя'}
const actionLabel=a=>actionMap[a]||a;const entityLabel=e=>({product:'Товар',category:'Категория',order:'Заказ',discount_rule:'Скидка',campaign:'Рассылка',user:'Пользователь'}[e]||e);const date=v=>new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v));const time=v=>new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(v))
</script>
<style scoped lang="scss">
.audit-page{background:#f8f5ef;min-height:calc(100dvh - 124px)}.audit-page__inner{max-width:1180px}.audit-head{margin-bottom:18px}.audit-head>span{color:#896742;font-size:11px;font-weight:850;letter-spacing:.09em;text-transform:uppercase}.audit-head h1{margin:5px 0 7px}.audit-head p{max-width:820px;margin:0;color:#786c60;line-height:1.55}.audit-filters{display:grid;grid-template-columns:1fr 1fr 170px 150px;gap:10px;padding:14px;margin-bottom:14px}.audit-list{display:grid;gap:8px}.audit-row{display:grid;grid-template-columns:110px minmax(220px,1fr) minmax(180px,.7fr) auto;align-items:center;gap:14px;padding:13px 15px;border-radius:15px}.audit-row__time,.audit-row__body,.audit-row__actor{display:grid;gap:3px;min-width:0}.audit-row__time strong{font-size:12px}.audit-row__time span,.audit-row__body span,.audit-row__actor span{color:#928577;font-size:10px}.audit-row__body strong{color:#3c2d1e;font-size:13px}.audit-row__body span,.audit-row__actor strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.audit-row__actor strong{font-size:11px}.audit-row details{position:relative}.audit-row summary{cursor:pointer;color:#765a3b;font-size:11px;font-weight:750}.audit-row pre{position:absolute;right:0;z-index:4;width:min(520px,80vw);max-height:300px;overflow:auto;padding:12px;border:1px solid #ddd0c0;border-radius:12px;background:#fff;color:#54493e;font-size:10px;white-space:pre-wrap}.audit-empty{padding:32px;text-align:center}@media(max-width:850px){.audit-filters{grid-template-columns:1fr 1fr}.audit-row{grid-template-columns:90px 1fr}.audit-row__actor,.audit-row details{grid-column:2}}@media(max-width:520px){.audit-filters{grid-template-columns:1fr}.audit-row{grid-template-columns:1fr}.audit-row__actor,.audit-row details{grid-column:auto}.audit-row pre{left:0;right:auto}}
</style>
